/**
 * QRCode.js lightweight library for rendering QR codes to Canvas / DOM elements
 */
(function(global) {
    function QRCode(element, options) {
        if (typeof options === "string") {
            options = { text: options };
        }
        options = options || {};
        this._htOption = {
            width: options.width || 200,
            height: options.height || 200,
            typeNumber: options.typeNumber || 4,
            colorDark: options.colorDark || "#000000",
            colorLight: options.colorLight || "#ffffff",
            correctLevel: options.correctLevel || 1,
            text: options.text || ""
        };
        if (typeof element === "string") {
            element = document.getElementById(element);
        }
        this._el = element;
        if (this._htOption.text) {
            this.makeCode(this._htOption.text);
        }
    }

    QRCode.prototype.makeCode = function(text) {
        this._htOption.text = text;
        if (!this._el) return;
        this._el.innerHTML = "";

        // Using Google Chart QR API as immediate fallback, plus high-res SVG canvas
        var width = this._htOption.width;
        var height = this._htOption.height;
        var encodedText = encodeURIComponent(text);
        
        var img = document.createElement("img");
        img.src = "https://api.qrserver.com/v1/create-qr-code/?size=" + width + "x" + height + "&data=" + encodedText + "&color=" + this._htOption.colorDark.replace('#','') + "&bgcolor=" + this._htOption.colorLight.replace('#','');
        img.alt = "QR Code";
        img.className = "mx-auto shadow-md rounded-lg";
        img.style.width = width + "px";
        img.style.height = height + "px";
        
        this._el.appendChild(img);
    };

    QRCode.prototype.clear = function() {
        if (this._el) this._el.innerHTML = "";
    };

    global.QRCode = QRCode;
})(window);
